/* GENERATED by tools/port_snap.py from Pappenheimer tools/snapsim/cover.js + toc.js. */
/* Cover page: the form's name, your result and what this book contains. Sets window.__COVER = {done:true}. */
window.PBookCover = window.PBookCover || {};
(function(){
  'use strict';
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  let el = null;
  const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const day = s => { const m = String(s || '').match(/^(\d{4})-(\d\d)-(\d\d)/); return m ? `${+m[3]} ${MON[+m[2] - 1]} ${m[1]}` : ''; };
  const mmss = t => Math.floor(t / 60) + ':' + String(Math.round(t % 60)).padStart(2, '0');
  const hm = t => t >= 3600 ? Math.floor(t / 3600) + ' h ' + Math.round((t % 3600) / 60) + ' min' : Math.round(t / 60) + ' min';
  const tone = p => p >= 75 ? 'good' : p >= 60 ? 'mid' : 'low';
  const VIEWS = {rr: 'Rapid Review + pathway', expl: 'Official explanation', explrep: 'Rapid Review + your explanation highlights'};
  const FILT = {wrong: 'incorrect', flagged: 'flagged', changed: 'changed answers', unstable: 'unstable'};

  function ring(p){
    const r = 15.9155, c = 2 * Math.PI * r, v = Math.max(0, Math.min(100, p));
    return `<svg viewBox="0 0 36 36" class="ring ${tone(p)}"><circle cx="18" cy="18" r="${r}" class="trk"/>`
      + `<circle cx="18" cy="18" r="${r}" class="val" stroke-dasharray="${(v / 100 * c).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 18 18)"/></svg>`;
  }
  const tile = (k, v, sub, cls = '') => `<div class="tile ${cls}"><div class="tk">${esc(k)}</div><div class="tv">${v}</div><div class="ts">${sub}</div></div>`;
  function bars(rows, max){
    return rows.map(([name, a, b, cls]) => {
      const w = max ? a / max * 100 : b ? a / b * 100 : 0;
      return `<div class="br"><div class="bn">${esc(name)}</div><div class="bt"><i class="${cls || ''}" style="width:${w.toFixed(1)}%"></i></div>`
        + `<div class="bv">${max ? a : Math.round(a / b * 100) + '%'}<span>${max ? '' : a + '/' + b}</span></div></div>`;
    }).join('');
  }

  function render(d){
    const s = d.summary || {}, bk = s.book || {}, sh = s.shadow;
    const pct = s.answered ? Math.round(s.correct / s.answered * 100) : 0;
    const wrong = (s.answered || 0) - (s.correct || 0);
    const codes = sh ? sh.codes || {} : {}, cnt = k => codes[k] || codes[String(k)] || 0;
    const unstable = cnt(5) + cnt(6) + cnt(7);
    const changes = (s.w2r || 0) + (s.r2w || 0) + (s.w2w || 0);
    const sel = (bk.filters || []).map(f => FILT[f] || f);
    const what = [sel.length ? sel.join(' or ') + ' questions' : (bk.items ? '' : 'all questions'), bk.items ? 'Q ' + bk.items : ''].filter(Boolean).join(' · ');

    // ---- by subject (weakest first) and, from ThunderShadow, why points were lost / shaky
    const short = (d.toc && d.toc.short) || {};       // same short system names as the contents page (no truncation)
    const subj = (s.subjects || []).slice(0, 9).map(([n, a, b]) => [short[n] || n, a, b, tone(a / b * 100)]);
    const lost = sh ? [1, 2, 3, 4].filter(cnt).map(k => [sh.labels[k], cnt(k), 0, 'low']) : [];
    const shaky = sh ? [5, 6, 7].filter(cnt).map(k => [sh.labels[k], cnt(k), 0, 'mid']) : [];
    const lmax = Math.max(1, ...lost.map(r => r[1]), ...shaky.map(r => r[1]));
    const left = subj.length > 1 ? `<section><h2>By system <small>weakest first</small></h2>${bars(subj)}</section>` : '';
    const right = sh && (lost.length || shaky.length) ? `<section><h2>Your ThunderShadow log <small>${sh.linked} entries</small></h2>`
      + (lost.length ? `<div class="sub">Why points were lost</div>${bars(lost, lmax)}` : '')
      + (shaky.length ? `<div class="sub">Right, but unstable</div>${bars(shaky, lmax)}` : '') + '</section>' : '';

    el.innerHTML = `
      <header>
        <div class="over">Revision book</div>
        <h1>${esc(d.prettyTitle || d.formTitle)}</h1>
        <div class="meta">${[d.completedLocal && d.completedLocal !== '?' ? 'Completed ' + day(d.completedLocal) : '', (s.n || 0) + ' questions',
          d.savedAt ? 'progress saved ' + day(d.savedAt) : ''].filter(Boolean).map(esc).join('<span class="dot">·</span>')}</div>
      </header>
      <div class="hero">
        <div class="score">${ring(pct)}<div class="sv"><b>${pct}%</b><span>${s.correct || 0} / ${s.answered || 0} correct</span></div></div>
        <div class="tiles">
          ${tile('Incorrect', wrong, wrong ? 'questions to fix first' : 'none', 'bad')}
          ${sh ? tile('Unstable', unstable, 'right, but shaky (ThunderShadow 5–7)', 'warn') : tile('Flagged', s.flagged || 0, `${s.flagged_right || 0} of them right`, 'warn')}
          ${tile('Time per question', s.timed ? mmss(s.time / s.timed) : '–', s.timed ? hm(s.time) + ' in total' : 'no timing saved')}
          ${tile('Changed away from right', s.r2w || 0, `${changes} answer changes · ${s.w2r || 0} ended right`)}
        </div>
      </div>
      ${left || right ? `<div class="two${left && right ? '' : ' one'}">${left}${right}</div>` : ''}
      <section class="inside">
        <h2>In this book</h2>
        <div class="facts">
          <div><span>Questions</span><b>${bk.questions || 0}</b><em>${esc(what)}</em></div>
          <div><span>Pages</span><b>${bk.pages || 0}</b><em>cover + contents + 2 questions a page</em></div>
          <div><span>Right side</span><b class="sm">${esc(VIEWS[bk.view] || bk.view || '')}</b><em>left side: stem + choices</em></div>
          <div><span>Highlights</span><b>${bk.highlights ? 'On' : 'Off'}</b><em>${bk.highlights ? 'your simulator highlights in yellow' : 'printed without your highlights'}</em></div>
        </div>
      </section>
      <div class="key"><b>Key</b>
        <span><i class="c ok">C</i>correct</span><span><i class="c me">D</i>your pick</span><span><i class="t f">1st</i>first answer</span>
        <span><s>struck</s></span><span><mark>highlight</mark></span>
        ${sh ? '<span><i class="t un">≈</i>unstable</span><span><i class="t mn">note</i>your rule</span>' : ''}
        ${bk.view === 'explrep' ? '<span><em class="it">italic</em>explanation highlights</span>' : ''}
        <span><i class="bx"></i>review ticks</span>
      </div>
      <footer><span>Print on A4 · cut along the dashed line to get 2 cards a page</span><span>Pappenheimer · ${esc(day(d.madeAt))}</span></footer>`;
  }

  window.PBookCover.cover = (target, d) => { el = target; render(d); };
})();

/* Contents page (page 2, the back of the cover): questions by system and by subject, with page numbers. Sets window.__TOC. */
window.PBookCover = window.PBookCover || {};
(function(){
  'use strict';
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  let el = null;
  const tone = p => p >= 75 ? 'good' : p >= 60 ? 'mid' : 'low';
  // [3,4,5,9] -> "3–5, 9"
  const ranges = ps => { const u = [...new Set(ps)].sort((a, b) => a - b), out = [];
    for (let i = 0; i < u.length; i++) { let j = i; while (j + 1 < u.length && u[j + 1] === u[j] + 1) j++; out.push(i === j ? u[i] : u[i] + '–' + u[j]); i = j; }
    return out.join(', '); };
  const qn = r => r[4] === 'w' ? `<b>${r[0]}</b>` : r[4] === 'u' ? `<i>${r[0]}</i>` : String(r[0]);

  function group(rows, col, names, short){
    return names.map(name => {
      const rs = rows.filter(r => r[col] === name);
      if (!rs.length) return '';
      const ps = rs.map(r => r[3]);
      return `<div class="row"><div class="rn">${esc((short && short[name]) || name)}<small>${rs.length} Q</small></div>`
        + (ranges(ps).length > 14 ? `<div class="rp long">p. ${ranges(ps)}</div>` : `<div class="rp">p. ${ranges(ps)}</div>`)
        + `<div class="rq">Q ${rs.slice().sort((a, b) => a[0] - b[0]).map(qn).join(' · ')}</div></div>`;
    }).join('');
  }

  function render(d){
    const t = d.toc, s = d.summary || {};
    const disc = (s.disciplines || []).map(([n, a, b]) => [n, a, b, tone(a / b * 100)]);
    const bars = disc.map(([name, a, b, cls]) => `<div class="br"><div class="bn">${esc(name)}</div><div class="bt"><i class="${cls}" style="width:${(a / b * 100).toFixed(1)}%"></i></div>`
      + `<div class="bv">${Math.round(a / b * 100)}%<span>${a}/${b}</span></div></div>`).join('');
    el.innerHTML = `
      <header>
        <div class="over">Contents</div>
        <h1>${esc(d.prettyTitle || d.formTitle)}</h1>
        <div class="meta">${t.rows.length} questions · ${t.sorted ? 'cards sorted by system, then subject' : 'cards in the form\'s order'}
          <span class="dot">·</span><span class="tkey">Q numbers: <b>red</b> = incorrect, <i>amber</i> = unstable</span></div>
      </header>
      <div class="cols">
        <section><h2>By system <small>${t.sorted ? 'in book order' : ''}</small></h2>${group(t.rows, 1, t.systems, t.short)}</section>
        <section><h2>By subject <small>Step 2 CK disciplines</small></h2>${group(t.rows, 2, t.subjects)}
          ${bars ? `<div class="perf"><h2>Whole form by subject</h2>${bars}</div>` : ''}</section>
      </div>
      <footer><span>Q = question number in the form · p. = page in this book</span><span>Pappenheimer</span></footer>`;
  }

  window.PBookCover.toc = (target, d) => { el = target; render(d); };
})();
;

